def reload_request(request):
    view = env.ref('hr_recruitment_custom.view_required_document_submission_request_form_controlled', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': request.x_name or 'Required Document Submission Request',
        'res_model': 'x_hr.applicant_required_document_submission_request',
        'res_id': request.id,
        'view_mode': 'form',
